301	pub fn info(command: &InfoCommand) -> StrResult<()> {
302	    let cmd = CliArguments::command();
303	
304	    let env = get_vars()?;
305	
306	    let runtime_features =
307	        parse_features(env.typst_features.as_deref().unwrap_or_default())?;
308	
309	    let font_paths = env
310	        .typst_font_paths
311	        .as_deref()
312	        .unwrap_or_default()
313	        .split(':')
314	        .filter(|s| !s.is_empty())
315	        .map(PathBuf::from)
316	        .collect::<_>();
317	
318	    let version = typst::utils::version();
319	    let value = Info {
320	        version: version.raw(),
321	        build: Build {
322	            commit: version.commit(),
323	            platform: Platform::new(),
324	            settings: Settings {
325	                self_update: cfg!(feature = "self-update"),
326	                http_server: cfg!(feature = "http-server"),
327	            },
328	        },
329	        features: runtime_features,
330	        fonts: Fonts {
331	            paths: font_paths,
332	            system: !env
333	                .typst_ignore_system_fonts
334	                .as_ref()
335	                .and_then(|val| parse_bool(&cmd, val, "TYPST_IGNORE_SYSTEM_FONTS"))
336	                .unwrap_or(false),
337	            embedded: !env
338	                .typst_ignore_embedded_fonts
339	                .as_ref()
340	                .and_then(|val| parse_bool(&cmd, val, "TYPST_IGNORE_EMBEDDED_FONTS"))
341	                .unwrap_or(false),
342	        },
343	        packages: Packages {
344	            package_path: env
345	                .typst_package_path
346	                .as_ref()
347	                .map(PathBuf::from)
348	                .or_else(|| FsPackages::system_data().map(|fs| fs.path().into())),
349	            package_cache_path: env
350	                .typst_package_cache_path
351	                .as_ref()
352	                .map(PathBuf::from)
353	                .or_else(|| FsPackages::system_cache().map(|fs| fs.path().into())),
354	        },
355	        env,
356	    };
357	
358	    if let Some(format) = command.format {
359	        let serialized = crate::serialize(&value, format, command.pretty)?;
360	        println!("{serialized}");
361	    } else {
362	        format_human_readable(&value).map_err(|e| eco_format!("{e}"))?;
363	    }
364	
365	    Ok(())
366	}
