368	/// Retrieves all relevant environment variables.
369	fn get_vars() -> StrResult<Environment> {
370	    fn get_var(key: &'static str) -> StrResult<Option<String>> {
371	        match std::env::var(key) {
372	            Ok(val) => Ok(Some(val)),
373	            Err(VarError::NotPresent) => Ok(None),
374	            Err(VarError::NotUnicode(_)) => {
375	                crate::set_failed();
376	                crate::print_error(&format!(
377	                    "the environment variable `{key}` was not valid UTF-8"
378	                ))
379	                .map_err(|e| eco_format!("{e}"))?;
380	                Ok(None)
381	            }
382	        }
383	    }
384	
385	    Ok(Environment {
386	        typst_cert: get_var("TYPST_CERT")?,
387	        typst_features: get_var("TYPST_FEATURES")?,
388	        typst_font_paths: get_var("TYPST_FONT_PATHS")?,
