390	        typst_ignore_embedded_fonts: get_var("TYPST_IGNORE_EMBEDDED_FONTS")?,
391	        typst_package_cache_path: get_var("TYPST_PACKAGE_CACHE_PATH")?,
392	        typst_package_path: get_var("TYPST_PACKAGE_PATH")?,
393	        typst_root: get_var("TYPST_ROOT")?,
394	        typst_update_backup_path: get_var("TYPST_UPDATE_BACKUP_PATH")?,
395	        source_date_epoch: get_var("SOURCE_DATE_EPOCH")?,
