449	/// A for formatting human readable key-value-description triplets.
450	struct KeyValDesc<'a> {
451	    key: &'static str,
452	    val: Value<'a>,
453	    desc: &'static str,
454	}
455	
456	impl KeyValDesc<'_> {
457	    /// Formatted this as `<key> <val> (<desc>)` with optional right padding for
458	    /// key and value.
459	    fn format(
460	        &self,
461	        out: &mut TermOut,
462	        key_pad: Option<usize>,
463	        val_pad: Option<usize>,
464	    ) -> io::Result<()> {
465	        write!(out, "  ")?;
466	        write_key(out, self.key, key_pad)?;
467	        write!(out, " ")?;
468	        self.val.format(out, val_pad)?;
469	        write!(out, " ({})", self.desc)?;
470	
471	        Ok(())
472	    }
473	}
