475	/// A value for colorful human readable formatting.
476	enum Value<'a> {
477	    Unset,
478	    Bool(bool),
479	    Path(&'a Path),
480	    String(&'a str),
481	}
482	
483	impl Value<'_> {
484	    /// Formats this value with optional right padding.
485	    fn format(&self, out: &mut TermOut, pad: Option<usize>) -> io::Result<()> {
486	        match self {
487	            Value::Unset => write_value_special(out, "<unset>", pad),
488	            Value::Bool(true) => write_value_special(out, "on", pad),
489	            Value::Bool(false) => write_value_special(out, "off", pad),
490	            Value::Path(val) => write_value_simple(out, val.display(), pad),
491	            Value::String(val) => write_value_simple(out, val, pad),
492	        }
493	    }
494	}
495	
496	/// Writes a key in cyan with optional right padding.
497	fn write_key(out: &mut TermOut, key: impl Display, pad: Option<usize>) -> io::Result<()> {
498	    out.set_color(ColorSpec::new().set_fg(Some(Color::Cyan)))?;
499	    if let Some(pad) = pad {
500	        write!(out, "{key: <pad$}")?;
501	    } else {
502	        write!(out, "{key}")?;
503	    }
504	    out.reset()?;
505	
506	    Ok(())
507	}
