515	    out.set_color(ColorSpec::new().set_fg(Some(Color::Green)))?;
516	    if let Some(pad) = pad {
517	        write!(out, "{val: <pad$}")?;
518	    } else {
519	        write!(out, "{val}")?;
520	    }
