24	impl TermOut {
25	    /// Clears the entire screen.
26	    pub fn clear_screen(&mut self) -> io::Result<()> {
27	        // We don't want to clear anything that is not a TTY.
28	        if self.inner.stream.supports_color() {
29	            let mut stream = self.inner.stream.lock();
30	            // Clear the screen and then move the cursor to the top left corner.
31	            write!(stream, "\x1B[2J\x1B[1;1H")?;
32	            stream.flush()?;
33	        }
34	        Ok(())
35	    }
36	
37	    /// Clears the previously written line.
38	    pub fn clear_last_line(&mut self) -> io::Result<()> {
39	        // We don't want to clear anything that is not a TTY.
40	        if self.inner.stream.supports_color() {
41	            // First, move the cursor up `lines` lines.
42	            // Then, clear everything between the cursor to end of screen.
43	            let mut stream = self.inner.stream.lock();
44	            write!(stream, "\x1B[1F\x1B[0J")?;
45	            stream.flush()?;
46	        }
47	        Ok(())
48	    }
49	}
50	
51	impl Write for TermOut {
52	    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
53	        self.inner.stream.lock().write(buf)
54	    }
55	
56	    fn flush(&mut self) -> io::Result<()> {
57	        self.inner.stream.lock().flush()
58	    }
59	}
60	
61	impl WriteColor for TermOut {
62	    fn supports_color(&self) -> bool {
63	        self.inner.stream.supports_color()
64	    }
65	
66	    fn set_color(&mut self, spec: &termcolor::ColorSpec) -> io::Result<()> {
67	        self.inner.stream.lock().set_color(spec)
68	    }
69	
70	    fn reset(&mut self) -> io::Result<()> {
71	        self.inner.stream.lock().reset()
72	    }
73	}
74	
75	/// The stuff that has to be shared between instances of [`TermOut`].
76	struct TermOutInner {
77	    stream: termcolor::StandardStream,
78	}
79	
80	impl TermOutInner {
81	    fn new() -> Self {
82	        let color_choice = match ARGS.color {
