84	                ColorChoice::Auto
85	            }
86	            clap::ColorChoice::Always => ColorChoice::Always,
87	            _ => ColorChoice::Never,
88	        };
89	
90	        let stream = termcolor::StandardStream::stderr(color_choice);
91	        TermOutInner { stream }
92	    }
